              "type": "string"
            },
            "resume_offset": {
              "type": "integer"
            },
            "resume_sequence": {
              "type": "integer"
            },
            "resume_timestamp": {
              "type": "string",
              "format": "date-time"
            },
            "resume_status": {
              "type": "string",
              "enum": ["pending", "in-progress", "completed", "failed"]
            }
          }
        },
        "kv_crc": {
          "type": "integer"
        }
      }
    }
  }
}
